window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["agent-skills"]={"title":"智能体技能：把重复任务封装成可发现、可验证、可治理的能力包","subtitle":"从触发描述、渐进披露、脚本与资产，到选择混淆、权限、版本和回归，理解技能与提示、工具和工作流的边界。","thesis":"技能不是更长的提示词，而是围绕明确任务封装触发条件、步骤、资源、脚本和验收的版本化制品；它能规模化正确做法，也会规模化<b>过时规则、高权限动作和供应链风险</b>。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"输入为已核验CSV和报告日期","rule":"数字逐项回连中间JSON","steps":"生成文档后调用渲染脚本","interpretation":"不负责清洗缺失数据或凭空补全事实"}},{"section":5,"evidence":{"setup":"100个请求里只有20个真正需要技能S","rule":"精确率衡量触发中有多少选对","steps":"精确率为18/(18+16)","interpretation":"高风险低基率场景应优先减少误触发"}}],"formulas":[{"id":"agent-skills-selection","section":5,"formulaIndex":1,"symbols":[{"name":"Precision","meaning":"所有技能触发中选择正确的比例","evidence":"Precision 是触发结果中正确的比例"},{"name":"Recall","meaning":"真实需要某技能的请求中被触发的比例","evidence":"Recall 是真实需要请求中被找回的比例"},{"name":"TP","meaning":"真实需要且正确触发技能的请求数量","evidence":"TP 是正确触发技能的请求数"},{"name":"FP","meaning":"不需要技能却被错误触发的请求数量","evidence":"FP 是不需要技能却误触发的请求数"},{"name":"FN","meaning":"需要技能却没有触发的请求数量","evidence":"FN 是需要技能却未触发的请求数"}]}],"termReviews":[{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"渐进披露","meaning":"发现时只加载轻量描述，选中后再按需加载完整资源","purpose":"减少未选技能材料占用上下文和干扰选择","definitionEvidence":"扩展资源按任务逐步加载","purposeEvidence":"避免把整套文档永久塞进上下文"},{"name":"schema","meaning":"规定输入输出字段、类型和约束的机器可检查契约","purpose":"让技能、脚本和组合之间能校验中间制品","definitionEvidence":"字段、文件、schema与示例","purposeEvidence":"输入/输出"}]},{"section":7,"reviewedAt":"2026-07-27","terms":[{"name":"幂等","meaning":"重复执行同一动作仍只产生一次预期副作用","purpose":"防止重试脚本造成重复写入","definitionEvidence":"错误码、幂等、超时","purposeEvidence":"约束副作用"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"智能体技能是重复任务的版本化能力包。","evidence":"智能体技能是把一类重复任务的触发、步骤、资源和验收封装成版本化能力包"},"problem":{"answer":"它减少重复设计并规模化已经验证的做法。","evidence":"通过固化已验证做法减少重复设计"},"inputOutput":{"answer":"输入任务轨迹和通过条件，输出复用制品。","evidence":"输入是多次真实任务轨迹与稳定通过条件，输出是可发现、可执行、可回退的复用制品"},"mechanism":{"answer":"从成功失败轨迹提炼稳定步骤并保留回退。","evidence":"先从真实成功/失败轨迹提炼稳定部分"},"interpretation":{"answer":"封装表示稳定部分能够复用。","evidence":"技能的收益来自复用"},"boundary":{"answer":"目标持续变化或不可验收时应回退通用 Agent。","evidence":"应回退通用 Agent"}},{"section":2,"definition":{"answer":"提示工具技能工作流是责任不同的四类制品。","evidence":"输出提示、工具、技能或工作流分类"},"problem":{"answer":"它解决四者都指导 Agent 时怎样区分的问题。","evidence":"四者都能“告诉 Agent 怎么做”，差别在哪里"},"inputOutput":{"answer":"输入制品及责任，输出对应层级分类。","evidence":"输入一个 Agent 制品及其责任，输出提示、工具、技能或工作流分类"},"mechanism":{"answer":"按本轮表达动作任务方法和持久状态区分。","evidence":"提示指导本轮表达，工具提供动作，技能组织某类任务，工作流持久编排系统状态"},"interpretation":{"answer":"四类制品可以组合但不能互相替代。","evidence":"四者可以组合但不能互相替代"},"boundary":{"answer":"技能不授予权限也不保证现实副作用安全。","evidence":"不保证执行器的现实副作用安全"}},{"section":3,"definition":{"answer":"技能包由描述输入输出步骤资源脚本治理六类契约组成。","evidence":"一个技能包至少包含六类契约"},"problem":{"answer":"它解决只有 README 时难以稳定复用的问题。","evidence":"为什么难以稳定复用"},"inputOutput":{"answer":"输入六类信息，输出可独立执行验收的能力包。","evidence":"输入适用任务、数据契约、操作步骤、参考资源、脚本和治理信息，输出能够独立执行与验收的六类契约"},"mechanism":{"answer":"入口完整读取，扩展按需加载，确定工作交脚本。","evidence":"入口必须完整读取，扩展资料按需加载"},"interpretation":{"answer":"六类齐全表示责任和依赖可追踪。","evidence":"六类齐全表示责任可追踪"},"boundary":{"answer":"依赖变化后仍须回归，不能假设永远正确。","evidence":"依赖变化后仍须回归"}},{"section":4,"definition":{"answer":"PDF 案例把写作脚本模板和验收封装为技能。","evidence":"生成并验收月度PDF报告"},"problem":{"answer":"它解决散落提示和资产怎样形成可靠能力。","evidence":"它解决散落提示、脚本和品牌模板如何形成可靠能力的问题"},"inputOutput":{"answer":"输入 CSV 日期品牌，输出 PDF 校验版本警告。","evidence":"输入已核验 CSV、报告日期和品牌规则，输出 PDF、校验报告、完整版本和未解决警告"},"mechanism":{"answer":"脚本算数模型解释渲染检查并回连证据。","evidence":"系统用脚本计算数字、模型解释趋势、渲染器检查版面"},"interpretation":{"answer":"通过表示本次内容与版式验收满足声明。","evidence":"通过表示本次制品满足声明的内容与版式验收"},"boundary":{"answer":"技能不负责清洗缺失数据或补全事实。","evidence":"不负责清洗缺失数据或凭空补全事实"}},{"section":5,"definition":{"answer":"技能选择是带请求基率的分类问题。","evidence":"选择技能是一个带基率的分类问题"},"problem":{"answer":"它解释高召回为何仍会频繁误触发。","evidence":"为什么仍可能频繁打扰用户"},"inputOutput":{"answer":"输入请求与描述，输出技能澄清或无技能。","evidence":"输入请求与技能描述，输出选中技能、澄清或无技能"},"mechanism":{"answer":"用 TP FP FN 计算精确率与召回率。","evidence":"18 个真阳性和 16 个假阳性"},"interpretation":{"answer":"百分之五十二点九表示近半触发错误。","evidence":"精确率仅 52.9%"},"boundary":{"answer":"比例依赖基率，高风险场景应优先减少误触发。","evidence":"高风险低基率场景应优先减少误触发"}},{"section":6,"definition":{"answer":"渐进披露把轻量发现与完整执行知识分开。","evidence":"发现时只看描述，选中后再渐进加载与验证"},"problem":{"answer":"它减少把所有技能全文放入上下文造成的竞争。","evidence":"减少上下文竞争"},"inputOutput":{"answer":"输入任务目录，输出入口和按需资源。","evidence":"输入任务和轻量描述目录，输出所选技能入口以及执行时按需加载的参考、脚本和资产"},"mechanism":{"answer":"先选描述再读入口并加载必要资源验收。","evidence":"选中后完整读取入口，再加载必要资源并验收"},"interpretation":{"answer":"它降低上下文竞争而不表示其他材料无用。","evidence":"不表示未加载材料无用"},"boundary":{"answer":"入口遗漏关键约束仍会使执行失真。","evidence":"入口遗漏关键约束仍会让后续执行失真"}},{"section":7,"definition":{"answer":"确定性脚本负责可重复计算转换和验证。","evidence":"脚本承担确定性工作"},"problem":{"answer":"它解决模型不擅长精确重复操作的问题。","evidence":"解决模型不擅长精确重复操作的问题"},"inputOutput":{"answer":"输入校验数据，输出结果和错误码。","evidence":"输入经过 schema 校验的数据，输出可重复计算、转换或验证结果及错误码"},"mechanism":{"answer":"用沙箱超时幂等和测试约束副作用。","evidence":"用沙箱、超时、幂等和测试约束副作用"},"interpretation":{"answer":"确定性只表示同条件下行为稳定。","evidence":"确定性只表示同条件下行为稳定"},"boundary":{"answer":"它不表示代码安全输入可信或写操作获批。","evidence":"不表示代码安全、输入可信或写操作已经批准"}},{"section":8,"definition":{"answer":"版本治理锁定入口资源脚本依赖和环境。","evidence":"版本要同时锁入口、资源、脚本和环境"},"problem":{"answer":"它解决只改参考文档也改变技能行为的问题。","evidence":"为什么也可能改变技能行为"},"inputOutput":{"answer":"输入完整依赖，输出不可变可重放版本集合。","evidence":"输入入口、资源、模板、脚本、依赖和运行环境，输出不可变技能版本与可重放的完整版本集合"},"mechanism":{"answer":"引用变化触发回归并回放高风险历史轨迹。","evidence":"任何引用变化都触发回归"},"interpretation":{"answer":"版本锁定支持解释旧结果。","evidence":"版本锁定支持解释旧结果"},"boundary":{"answer":"它不能阻止外部服务变化或链接失效。","evidence":"不能阻止外部服务变化"}},{"section":9,"definition":{"answer":"技能评测分选择正确和执行正确两层。","evidence":"评测分“选对技能”和“技能做对任务”两层"},"problem":{"answer":"它区分触发错误和技能执行错误。","evidence":"怎样区分触发错误与执行错误"},"inputOutput":{"answer":"输入请求反例任务基线，输出两层指标。","evidence":"输入请求集、近邻反例、确认选对的任务和旧版本基线，输出选择指标与执行指标"},"mechanism":{"answer":"先测选择再测步骤脚本制品权限。","evidence":"先判断是否选对技能，再判断步骤、脚本、制品和权限是否通过"},"interpretation":{"answer":"分层结果能定位失败发生在哪一层。","evidence":"从而定位失败层"},"boundary":{"answer":"总体分和漂亮案例不能代表异常失败分布。","evidence":"漂亮成功示例也不能代表异常输入分布"}},{"section":10,"definition":{"answer":"技能生命周期管理决定保留合并弃用禁用或回退。","evidence":"输出保留、合并、弃用、立即禁用或回退决定"},"problem":{"answer":"它解决过时重叠技能持续增加风险的问题。","evidence":"解决重叠和过时技能持续增加选择混淆与风险的问题"},"inputOutput":{"answer":"输入所有者使用失败依赖权限，输出生命周期决定。","evidence":"输入目录中的所有者、使用率、失败、依赖和权限状态，输出保留、合并、弃用、立即禁用或回退决定"},"mechanism":{"answer":"定期审计并在高风险漏洞时优先停止使用。","evidence":"高风险漏洞优先停止使用"},"interpretation":{"answer":"保留历史版本只用于解释旧产物。","evidence":"只用于解释旧产物"},"boundary":{"answer":"保留历史不表示旧技能仍可触发。","evidence":"不表示旧技能仍可触发"}},{"section":12,"definition":{"answer":"冲突解析决定多技能应选择组合澄清或回退。","evidence":"多个技能同时匹配时要显式消歧与组合"},"problem":{"answer":"它解决表格和文档技能同时命中时谁接管。","evidence":"“把Excel数据做成PDF汇报”同时命中表格和文档技能"},"inputOutput":{"answer":"输入候选契约权限冲突，输出选择组合或澄清。","evidence":"输入多个候选技能的输入输出、权限、依赖和冲突声明，输出单一选择、按 schema 组合、澄清或无技能回退"},"mechanism":{"answer":"先硬过滤再辨重叠互补并指定唯一所有者。","evidence":"先用硬条件过滤，再判断是重叠还是前后互补"},"interpretation":{"answer":"组合成功只表示接口能够衔接。","evidence":"组合成功只表示接口衔接"},"boundary":{"answer":"不能并发写同一资源或靠加载顺序决定权限。","evidence":"不能让两个技能并发写同一资源或靠加载顺序决定权限"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分技能、提示、工具和工作流；计算技能选择的精确率/召回率；设计渐进披露与确定性脚本；建立版本、权限和端到端回归。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>只有重复且可验收的任务值得封装<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">一次性的开放探索为什么不适合先写成技能？</p><p>技能的收益来自复用：反复加载同一规范、执行同一安全步骤、产生同类制品。任务若目标不断变化且无法定义通过条件，封装会过早固化错误假设。先从真实成功/失败轨迹提炼稳定部分，并保留通用Agent回退。</p><p>智能体技能是把一类重复任务的触发、步骤、资源和验收封装成版本化能力包。输入是多次真实任务轨迹与稳定通过条件，输出是可发现、可执行、可回退的复用制品。它通过固化已验证做法减少重复设计；目标持续变化或无法验收时，技能只会固化错误假设，应回退通用 Agent。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>技能、提示、工具和工作流处在不同层<span class=\"dd-badge eng\">概念消歧</span></h2><p class=\"dd-lead\">四者都能“告诉 Agent 怎么做”，差别在哪里？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>制品</th><th>主要回答</th><th>典型内容</th></tr></thead><tbody><tr><td>提示</td><td>这一轮怎样回答</td><td>指令与示例</td></tr><tr><td>工具</td><td>能执行什么动作</td><td>schema与执行器</td></tr><tr><td>技能</td><td>某类任务怎样完成</td><td>触发、流程、资源、验收</td></tr><tr><td>工作流</td><td>系统状态怎样持久流转</td><td>节点、分支、重试、补偿</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>初学者最易混淆：</b>技能可以调用工具或工作流，但它本身不授予权限，也不能替执行器保证副作用。</div><p>层级辨析输入一个 Agent 制品及其责任，输出提示、工具、技能或工作流分类。提示指导本轮表达，工具提供动作，技能组织某类任务，工作流持久编排系统状态；四者可以组合但不能互相替代。技能描述执行方法，不授予工具权限，也不保证执行器的现实副作用安全。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>一个技能包至少包含六类契约<span class=\"dd-badge eng\">结构</span></h2><p class=\"dd-lead\">只有一份 README 的技能为什么难以稳定复用？</p><ul class=\"dd-steps\"><li><b>描述：</b>适用、不适用和用户可见能力。</li><li><b>输入/输出：</b>字段、文件、schema与示例。</li><li><b>步骤：</b>按依赖排序，标关键判断与停止条件。</li><li><b>资源：</b>按需读取的参考、模板和资产。</li><li><b>脚本：</b>确定性计算、转换与验证。</li><li><b>治理：</b>版本、依赖、权限、负责人和回退。</li></ul><p>入口说明必须完整读取；扩展资源按任务逐步加载，避免把整套文档永久塞进上下文。</p><p>技能包结构输入适用任务、数据契约、操作步骤、参考资源、脚本和治理信息，输出能够独立执行与验收的六类契约。入口必须完整读取，扩展资料按需加载，确定性工作交给脚本。六类齐全表示责任可追踪，不表示脚本、模板或规则永远正确，依赖变化后仍须回归。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>完整示例：封装“生成并验收月度PDF报告”技能<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">如何把散落的写作提示、脚本和品牌模板变成可靠能力？</p><ol class=\"dd-steps\"><li>触发条件写明：输入为已核验CSV和报告日期，不负责数据清洗或事实补全。</li><li>入口读取字段字典与品牌规则，选择对应模板。</li><li>脚本计算汇总数字并输出机器可读中间JSON，模型只负责解释趋势。</li><li>生成文档后调用渲染脚本，检查页数、溢出、字体和表格。</li><li>数字逐项回连中间JSON，引用回连输入行；失败则停止而非交付。</li><li>输出PDF、校验报告、技能/模板/脚本版本和未解决警告。</li></ol><p>这比“请写一份漂亮报告”多出的不是文字，而是输入边界、确定性计算和验收闭环。</p><p>PDF 案例输入已核验 CSV、报告日期和品牌规则，输出 PDF、校验报告、完整版本和未解决警告。它解决散落提示、脚本和品牌模板如何形成可靠能力的问题。系统用脚本计算数字、模型解释趋势、渲染器检查版面，再把数字和引用回连输入。通过表示本次制品满足声明的内容与版式验收，不负责清洗缺失数据或凭空补全事实。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>选择技能是一个带基率的分类问题<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">选择准确率90%听起来很好，为什么仍可能频繁打扰用户？</p><p>100个请求里只有20个真正需要技能S。选择器召回18个正确请求（召回率18/20=90%），却误触发16个普通请求；精确率为18/(18+16)=<b>52.9%</b>。低基率下，即使召回高，描述重叠仍会让近半触发错误。</p><div class=\"dd-formula\" data-formula-id=\"agent-skills-selection\" data-display=\"mathml\"><math display=\"block\" aria-label=\"技能选择精确率等于真阳性除以真阳性加假阳性，召回率等于真阳性除以真阳性加假阴性\"><mi>Precision</mi><mo>=</mo><mfrac><mi>TP</mi><mrow><mi>TP</mi><mo>+</mo><mi>FP</mi></mrow></mfrac><mo>;</mo><mi>Recall</mi><mo>=</mo><mfrac><mi>TP</mi><mrow><mi>TP</mi><mo>+</mo><mi>FN</mi></mrow></mfrac></math></div><p class=\"dd-formula-note\"><code>TP</code> 是正确触发技能的请求数，<code>FP</code> 是不需要技能却误触发的请求数，<code>FN</code> 是需要技能却未触发的请求数；<code>Precision</code> 是触发结果中正确的比例，<code>Recall</code> 是真实需要请求中被找回的比例。</p><p>为相邻技能准备对比反例，允许“无技能”选项；高副作用技能宁可先澄清，不以强制高召回牺牲精确率。</p><p>技能选择输入请求与技能描述，输出选中技能、澄清或无技能。精确率衡量触发中有多少选对，召回率衡量真正需要时找回多少；示例中 18 个真阳性和 16 个假阳性使精确率仅 52.9%。这些比例依赖请求基率，高风险低基率场景应优先减少误触发。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>原创图：发现时只看描述，选中后再渐进加载与验证<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">为什么把所有技能全文放进系统提示会同时变慢和变差？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 320\" role=\"img\" aria-label=\"请求先匹配轻量技能描述，选择后加载完整入口，再按需读取参考脚本和资产，受限执行并验收制品\"><defs><marker id=\"as29\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"18\" y=\"112\" width=\"95\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"65\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\">用户任务</text><text x=\"65\" y=\"163\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">目标 / 输入</text><path d=\"M113,147 L153,147\" stroke=\"#788293\" marker-end=\"url(#as29)\"/><rect x=\"158\" y=\"82\" width=\"125\" height=\"130\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"220\" y=\"112\" text-anchor=\"middle\" class=\"svg-t\">描述目录</text><text x=\"220\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">适用 / 不适用</text><text x=\"220\" y=\"160\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">轻量发现</text><text x=\"220\" y=\"188\" text-anchor=\"middle\" class=\"svg-t\">选择或无技能</text><path d=\"M283,147 L323,147\" stroke=\"#788293\" marker-end=\"url(#as29)\"/><rect x=\"328\" y=\"82\" width=\"125\" height=\"130\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"390\" y=\"112\" text-anchor=\"middle\" class=\"svg-t\">完整入口</text><text x=\"390\" y=\"138\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">步骤 / 失败</text><text x=\"390\" y=\"160\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">权限 / 验收</text><text x=\"390\" y=\"188\" text-anchor=\"middle\" class=\"svg-t\">必须完整读取</text><path d=\"M453,147 L493,147\" stroke=\"#788293\" marker-end=\"url(#as29)\"/><rect x=\"498\" y=\"42\" width=\"120\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"498\" y=\"124\" width=\"120\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"498\" y=\"206\" width=\"120\" height=\"72\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"558\" y=\"72\" text-anchor=\"middle\" class=\"svg-t\">按需参考</text><text x=\"558\" y=\"94\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">字段/规范</text><text x=\"558\" y=\"154\" text-anchor=\"middle\" class=\"svg-t\">脚本</text><text x=\"558\" y=\"176\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">计算/验证</text><text x=\"558\" y=\"236\" text-anchor=\"middle\" class=\"svg-t\">资产</text><text x=\"558\" y=\"258\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">模板/示例</text><path d=\"M618,78 L655,128\" stroke=\"#788293\" marker-end=\"url(#as29)\"/><path d=\"M618,160 L655,160\" stroke=\"#788293\" marker-end=\"url(#as29)\"/><path d=\"M618,242 L655,192\" stroke=\"#788293\" marker-end=\"url(#as29)\"/><rect x=\"660\" y=\"110\" width=\"60\" height=\"100\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"690\" y=\"140\" text-anchor=\"middle\" class=\"svg-t\">执行</text><text x=\"690\" y=\"163\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">制品</text><text x=\"690\" y=\"185\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">验收</text></svg><figcaption>图 1　渐进披露把“发现成本”和“执行所需知识”分开，减少上下文竞争。</figcaption></figure><p>渐进披露输入任务和轻量描述目录，输出所选技能入口以及执行时按需加载的参考、脚本和资产。发现阶段只比较适用边界，选中后完整读取入口，再加载必要资源并验收。它降低上下文竞争，不表示未加载材料无用；入口遗漏关键约束仍会让后续执行失真。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>脚本承担确定性工作，也必须像产品代码治理<span class=\"dd-badge eng\">执行</span></h2><p class=\"dd-lead\">把计算放进脚本后，技能就自动可靠吗？</p><p>脚本优先处理解析、计算、格式转换和验证，但要有输入schema、错误码、幂等、超时、沙箱和测试。默认只读，写操作展示差异并请求批准；路径、网络与凭证范围最小化。不能用脚本输出掩盖源数据或把秘密写进日志。</p><p>确定性脚本输入经过 schema 校验的数据，输出可重复计算、转换或验证结果及错误码。它解决模型不擅长精确重复操作的问题，并用沙箱、超时、幂等和测试约束副作用。确定性只表示同条件下行为稳定，不表示代码安全、输入可信或写操作已经批准。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>版本要同时锁入口、资源、脚本和环境<span class=\"dd-badge eng\">演进</span></h2><p class=\"dd-lead\">只改一份参考文档，为什么也可能改变技能行为？</p><p>技能版本清单记录入口、所有引用资源、模板、脚本、依赖和兼容的模型/运行时。发布不可变版本并保留迁移说明；运行记录解析后的完整版本集合。高风险更新先回放历史任务，比较选择、工具轨迹、制品和权限。</p><p>外部链接不是稳定依赖，应快照、校验哈希或在不可用时明确失败。</p><p>版本治理输入入口、资源、模板、脚本、依赖和运行环境，输出不可变技能版本与可重放的完整版本集合。任何引用变化都触发回归，高风险更新先回放历史轨迹。版本锁定支持解释旧结果，但不能阻止外部服务变化；链接失效时必须明确失败而非静默换内容。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测分“选对技能”和“技能做对任务”两层<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">端到端失败时，怎样区分触发错误与执行错误？</p><p>选择层用正例、近邻反例、无技能请求测精确率/召回率、澄清率和错配成本；执行层在确认选择正确后测任务成功、步骤遵循、脚本通过、制品质量、权限违规、token/时间节省和人工纠正。</p><p>与通用Agent、仅提示和旧技能版本比较；按输入缺失、环境变化和异常数据切片。漂亮示例不能代替失败分布。</p><p>两层评测输入请求集、近邻反例、确认选对的任务和旧版本基线，输出选择指标与执行指标。先判断是否选对技能，再判断步骤、脚本、制品和权限是否通过，从而定位失败层。总体端到端分数不能区分误触发与执行错误，漂亮成功示例也不能代表异常输入分布。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>技能需要下线与回退，不应只增不减<span class=\"dd-badge eng\">生命周期</span></h2><p class=\"dd-lead\">两个技能功能重叠时继续共存会怎样？</p><p>目录定期审计所有者、使用率、失败、依赖和权限。合并重叠描述，弃用前给替代和期限；高风险漏洞可立即禁用并回到通用流程。删除技能时仍保留版本与历史运行证据，保证旧产物可解释。</p><p>技能生命周期管理输入目录中的所有者、使用率、失败、依赖和权限状态，输出保留、合并、弃用、立即禁用或回退决定。它解决重叠和过时技能持续增加选择混淆与风险的问题。删除后保留历史版本和运行证据只用于解释旧产物，不表示旧技能仍可触发；高风险漏洞优先停止使用。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">技能的成熟度看可验证复用，不看提示词长度。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>技能就是长提示</td><td>还包含触发、资源、脚本、验收与治理</td></tr><tr><td>技能可授予工具权限</td><td>权限由运行时和执行器独立控制</td></tr><tr><td>描述越宽越容易命中</td><td>会降低低基率场景下的精确率</td></tr><tr><td>所有资料应一次加载</td><td>发现轻量、执行渐进披露</td></tr><tr><td>发布后永久复用</td><td>依赖、规则和风险都会过期</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>提示、工具调用、结构化输出</td></tr><tr><td><b>本页核心</b></td><td>触发、渐进披露、脚本、验收、版本</td></tr><tr><td>相邻</td><td>Agent框架、工作流、MCP</td></tr><tr><td>工程</td><td>沙箱、依赖锁定、灰度与下线</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">12</span>多个技能同时匹配时要显式消歧与组合<span class=\"dd-badge eng\">冲突解析</span></h2><p class=\"dd-lead\">“把Excel数据做成PDF汇报”同时命中表格和文档技能，该由谁接管？</p><p>选择器先按硬条件过滤输入类型、输出制品和权限，再按描述相关度排序；若两个技能分别承担前后阶段，管理者可按声明的输入输出组合，而不是任选一个。组合必须有唯一所有者和中间制品schema，防止两个技能都编辑同一文件。</p><p>技能声明 <code>conflicts_with</code>、<code>requires</code> 和可组合接口。高风险冲突或置信差距小则向用户澄清；不要让先加载的技能凭上下文位置获得隐式优先权。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>情况</th><th>策略</th><th>验证</th></tr></thead><tbody><tr><td>同目标重叠技能</td><td>选更具体且版本受支持者</td><td>近邻反例</td></tr><tr><td>前后阶段互补</td><td>按schema串联</td><td>中间制品契约</td></tr><tr><td>同时写同一资源</td><td>禁止并发或设唯一所有者</td><td>diff/锁</td></tr><tr><td>低置信高风险</td><td>澄清或无技能回退</td><td>人工批准</td></tr></tbody></table></div><p>冲突解析输入多个候选技能的输入输出、权限、依赖和冲突声明，输出单一选择、按 schema 组合、澄清或无技能回退。先用硬条件过滤，再判断是重叠还是前后互补，并为共同资源指定唯一所有者。组合成功只表示接口衔接，不能让两个技能并发写同一资源或靠加载顺序决定权限。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>识别重复且可验收任务</li><li>从成功失败轨迹提炼稳定步骤</li><li>写适用/不适用和输入输出</li><li>把确定工作放入受限脚本</li><li>按需组织参考与资产</li><li>分别评测选择和执行</li><li>锁定完整依赖并灰度发布</li><li>监控、升级、合并或下线</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>技能与工具的核心差别？</li><li>低基率下为何要关注精确率？</li><li>渐进披露解决什么？</li><li>脚本为何仍需权限和测试？</li><li>技能评测为何分两层？</li><li>假设“智能体技能：把重复任务封装成可发现、可验证、可治理的能力包”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“智能体技能：把重复任务封装成可发现、可验证、可治理的能力包”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“智能体技能：把重复任务封装成可发现、可验证、可治理的能力包”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>工具定义能执行什么动作，技能定义某类任务如何组合指令、资源、工具与验收。</li><li>即使召回高，少量误触发也可能占全部触发的大比例。</li><li>发现时只加载轻量描述，选中后按需读取完整知识，减少上下文竞争。</li><li>确定性不等于安全，脚本同样可能误写、泄密或在环境变化后失败。</li><li>要区分选择器选错与技能本身执行失败。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2305.16291\" target=\"_blank\" rel=\"noopener\">Voyager</a>：可复用技能库与自动课程</li><li><a href=\"https://arxiv.org/abs/2302.04761\" target=\"_blank\" rel=\"noopener\">Toolformer</a>：模型学习调用工具</li><li><a href=\"https://arxiv.org/abs/2210.03629\" target=\"_blank\" rel=\"noopener\">ReAct</a>：行动与观察闭环</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
